import Root from "./1Adding Interactivity/5UpdatingArrays"
import Sub from "./subReLearn"
import "./ReLearn.css"

export default function () {
  return (
    <>
    <Screen/>
    </>
  );
}


import { useImmer } from "use-immer"
import { useState } from "react"
const initialNum = [{val: 0}]
export function Screen() {
  const [num, setNum] = useState(initialNum)
  const [otherNum, setOtherNum] = useState(initialNum)
  function change() {
    let numbre = num
    numbre = 10
    setNum(numbre)
  }
  function otherChange() {
    let numbre = otherNum
    numbre.val = 10
    setOtherNum(numbre)
  }
  function reset() {
    setNum(initialNum)
    setOtherNum(initialNum)
  }
  return (
    <>
    <Elem content={num} func={change}/>
    <Elem content={otherNum} func={otherChange}/>
    </>
  );
}

function Elem({content, func}) {
  return <>{content.val} <button onClick={func}>click</button><br/></>
}


// http://localhost:3000
